13	// hookStoreFileName is the per-session record cmux's `cmux hooks claude <event>`
14	// CLI maintains under ~/.cmuxterm/.
15	const hookStoreFileName = "claude-hook-sessions.json"
16	
17	// maxHookStoreBytes bounds how much of the store is parsed. It holds one small
18	// record per session; anything this large is corrupt, not a real store.
19	const maxHookStoreBytes = 8 * 1024 * 1024
20	
21	// hookSessionRecord is the subset of a store record this bridge needs.
22	//
23	// transcriptPath is the authoritative field: Claude Code hands every hook its
24	// own `transcript_path`, and cmux writes it through verbatim. Deriving the path
25	// instead (encode the cwd, glob for <session>.jsonl) guesses at a layout that
26	// does not always hold — a session under a non-default CLAUDE_CONFIG_DIR, or a
27	// workflow session whose file sits in a nested directory, is simply not where
28	// the glob looks.
29	type hookSessionRecord struct {
30		SessionID      string  `json:"sessionId"`
31		SurfaceID      string  `json:"surfaceId"`
32		CWD            string  `json:"cwd"`
33		TranscriptPath string  `json:"transcriptPath"`
34		PID            int     `json:"pid"`
35		UpdatedAt      float64 `json:"updatedAt"`
36	}
37	
38	type hookActiveSession struct {
39		SessionID string `json:"sessionId"`
40	}
41	
42	type hookStoreFile struct {
43		// The session each surface is CURRENTLY running, maintained by the hook
44		// lifecycle. This is the freshest surface → session binding available.
45		ActiveSessionsBySurface map[string]hookActiveSession `json:"activeSessionsBySurface"`
46		// Every remembered session, keyed by session id.
47		Sessions map[string]hookSessionRecord `json:"sessions"`
48	}
49	
50	// hookStore reads the cmux hook session store, caching the parsed file until it
51	// changes on disk. The store is rewritten on every hook event (many per second
52	// during a tool storm), so re-parsing it per request would be wasteful; a
53	// stat-guarded cache keeps a poll cheap.
54	type hookStore struct {
55		path string
56	
57		mu      sync.Mutex
58		modTime time.Time
59		size    int64
60		parsed  *hookStoreFile
61	}
62	
63	func newHookStore(home string) *hookStore {
64		return &hookStore{path: filepath.Join(home, ".cmuxterm", hookStoreFileName)}
65	}
66	
67	// load returns the parsed store, or nil when it is absent or unreadable. A
68	// missing store is normal (cmux not installed, or no agent has run yet) and is
69	// never an error here — the caller falls back to path derivation.
70	func (s *hookStore) load() *hookStoreFile {
71		info, err := os.Stat(s.path)
72		if err != nil || !info.Mode().IsRegular() || info.Size() > maxHookStoreBytes {
73			return nil
74		}
75	
76		s.mu.Lock()
77		defer s.mu.Unlock()
78	
79		if s.parsed != nil && s.modTime.Equal(info.ModTime()) && s.size == info.Size() {
80			return s.parsed
81		}
82	
83		// LimitReader, not ReadFile: the CLI rewrites this file on every hook event,
84		// so the size the guard above checked can be stale by the time it is opened.
85		f, err := os.Open(s.path)
86		if err != nil {
87			return nil
88		}
89		data, err := io.ReadAll(io.LimitReader(f, maxHookStoreBytes))
90		f.Close()
91		if err != nil {
92			return nil
93		}
94		var file hookStoreFile
95		if err := json.Unmarshal(data, &file); err != nil {
96			// A torn read (the CLI rewrites this file under a lock we don't hold)
97			// parses as garbage. Keep serving the last good parse rather than
98			// dropping to the glob for one poll.
99			return s.parsed
100		}
101		s.parsed = &file
102		s.modTime = info.ModTime()
103		s.size = info.Size()
104		return s.parsed
105	}
106	
107	// activeBySurface returns the session the store says a surface is running right
108	// now. This is the store's own authoritative pointer, so it is the only
109	// surface-keyed lookup allowed to override a resolution the surface's
110	// checkpoint could not satisfy.
111	func (s *hookStore) activeBySurface(surfaceID string) (hookSessionRecord, bool) {
112		if surfaceID == "" {
113			return hookSessionRecord{}, false
114		}
115		file := s.load()
116		if file == nil {
117			return hookSessionRecord{}, false
118		}
119		for key, active := range file.ActiveSessionsBySurface {
120			if !strings.EqualFold(key, surfaceID) {
121				continue
122			}
123			rec, ok := lookupSession(file, active.SessionID)
124			if !ok {
125				return hookSessionRecord{}, false
126			}
127			// The pointer and the record must agree about which surface this is.
128			// They are written by the same hooks, so a disagreement means the store
129			// is stale or inconsistent — and following it hands this surface's
130			// client another surface's conversation.
131			if rec.SurfaceID != "" && !strings.EqualFold(rec.SurfaceID, surfaceID) {
132				return hookSessionRecord{}, false
