func gifBytes() []byte   { return append([]byte("GIF89a"), bytes.Repeat([]byte{0}, 32)...) }
func webpBytes() []byte  { b := []byte("RIFF____WEBPVP8 "); return append(b, bytes.Repeat([]byte{0}, 32)...) }
